all_records={r['cve']:r for r in json.load(open(D/'cve-evidence/range-records.json'))}
old=json.load(open(D/'selection.json')); previous={r['cve']:r for r in old['entries']}
manual={r['cve']:r for r in json.load(open(D/'cve-evidence/manual-triage.json'))}
supp={r['cve']:r for r in json.load(open(D/'supplemental-critical-evidence/dispositions.json'))}
published=set((D/'platform-evidence/dedup-cves.txt').read_text().split())
BASE='a2384967b90f24d2470c9eb15f0e66d938df7e08'
OS='87fc13aac3fc8ce3d6c71c7ef3a8e72a5993a088'
CNA='56fdb3bed3f95b64b83c9f1a42ccb603452ec5c9'
G={
 'config':{'file':'platform-evidence/frozen-6.12.95-dot-config.txt','provenance':'platform-evidence/frozen-config-provenance.json','config_sha256':'c10922b492fdf39ed3027b9c8f7ce2846a5d3799d57d417a161595fa81a64969','linux_revision':BASE,'scope':'Exact archived 6.12.95 build, producing OS c065fa2f8485399737e20e8ef9e44299d0766654; not a deployed-node or other-build inventory.'},
 'seccomp':{'file':'platform-evidence/source/lxc/config/templates/common.seccomp','url':'https://github.com/vpsfreecz/lxc/blob/267e7844c122b9be56ca8a1ccc3d2f4d8986c326/config/templates/common.seccomp#L6','scope':'Reference common.seccomp explicitly returns EPERM for open_by_handle_at. Profile overrides and running filters were not collected.'},
 'bpf':{'files':['platform-evidence/source/linux/kernel/bpf/syscall.c','supplemental-critical-evidence/source/linux/kernel/bpf/token.c'],'urls':['https://github.com/vpsfreecz/linux/blob/'+BASE+'/kernel/bpf/syscall.c#L2687','https://github.com/vpsfreecz/linux/blob/'+BASE+'/kernel/bpf/token.c#L16'],'scope':'Program-load/type capabilities use initial user namespace without a token; a token uses its delegated namespace and allowed command/map/program/attach masks. Host-installed programs or real token delegation were not measured.'},
 'module':{'file':'platform-evidence/source/vpsadminos/os/modules/config/kernel.nix','url':'https://github.com/vpsfreecz/vpsadminos/blob/'+OS+'/os/modules/config/kernel.nix#L159','matrix':'platform-baseline.md','scope':'Pinned source defaults disable autoload; relevant modules absent default preload. Built m plus these defaults is not an actual loaded-module snapshot or proof of historical absence.'},
 'cifs':{'files':['supplemental-critical-evidence/source/linux/fs/smb/client/cifsfs.c','supplemental-critical-evidence/source/linux/fs/super.c'],'urls':['https://github.com/vpsfreecz/linux/blob/'+BASE+'/fs/smb/client/cifsfs.c#L1111','https://github.com/vpsfreecz/linux/blob/'+BASE+'/fs/super.c#L688'],'matrix':'platform-baseline.md','scope':'Exact .95 cifs/smb3 registrations lack FS_USERNS_MOUNT; mount_capable requires initial-namespace CAP_SYS_ADMIN. Package A also checked .113 registrations. Existing host-prepared/delegated mounts remain unknown.'},
 'followup':{'file':'platform-evidence/followup-candidate-gates.json','matrix':'platform-baseline.md','scope':'Candidate-specific source gates; no deployed runtime or typed historical evidence.'}}
rows=[]
def add(ids,decision,exposure,group,primitive,benefit,scope,next_evidence,gate_keys,limit=None):
 for n in ids.split():
  cve='CVE-2026-'+n;r=all_records[cve];assert cve in manual or cve in supp
  f=r['fixes'][0];raw=json.load(open(D/'cve-evidence/records'/(cve+'.json')))
  assert raw['cveMetadata']['state']=='PUBLISHED' and cve not in published
  assert previous.get(cve,{}).get('decision')!='recommended'
  starts=[v['version'] for a in r['affected'] for v in a.get('versions',[]) if v.get('versionType')=='git' and v.get('lessThan')==f['sha']]
  before=previous.get(cve,{}).get('decision') or manual.get(cve,{}).get('tier') or supp.get(cve,{}).get('disposition')
  rows.append({'cve':cve,'title':r['title'],'selection_decision':decision,'selection_group':group,'member_benefit':benefit,'exposure':{'conclusion':exposure,'exact_scope':scope,'source_gate_refs':gate_keys,'node_roles':'Any role using the exact build for build-negative rows; otherwise tenant path only, host/storage workload not assessed.','calendar_period':'No observed deployment interval; source/build/profile scope only.','current_deployed_status':'unknown','historical_fleet_interval':'unknown; exact archived build/profile evidence must not become a fleet-never-vulnerable claim.','mitigation_state':'not assessed per node; upstream fix release is source history, not activation proof.'},'primitive':primitive,'attacker_prerequisites':scope,'evidence_strength':limit or 'Primary defect description plus inherited pinned source-gate review; no exploit or production observation. Kernel corruption is not a demonstrated VPS-root/host-root/cross-VPS exploit.','primary_status':'PUBLISHED','primary_url':r['cna_url'],'primary_snapshot':CNA,'source_access_date':'2026-10-19','fix_release':f['release'],'fix_sha':f['sha'],'fix_url':'https://git.kernel.org/stable/c/'+f['sha'],'git_introduction_sha':starts,'all_primary_affected_intervals':r['affected'],'correction_exception':None,'known_downstream_correction':'See inherited historical livepatch mapping where applicable; no runtime activation is asserted.','cvss':{'authority':'Linux CNA','metrics':r['metrics'],'publication_date':'not supplied by retained record metadata; access date is separate'},'dedup':{'public_57_cve_set':'not present','repository_dossier_set':'not present (all repository dossiers are in public set)','private_drafts':'unknown; not accessible in this public/source phase'},'previous_decision':before,'previous_decision_source':'selection.json' if cve in previous else 'cve-evidence/manual-triage.json' if cve in manual else 'supplemental-critical-evidence/dispositions.json','reason_for_revision':'Broader user policy admits useful high-threat negative/conditional assessments. This revises selection-worthiness only; underlying exposure findings and original 41 are preserved.','approval_state':'research proposal; no dossier/draft/publication approval','next_evidence_before_dossier':next_evidence})
add('80585 80586 80587','propose','not_affected','exact-build-negative','MPTCP Fast Open stale state (80585), malformed DSS stale/uninitialized fields (80586), and conflicting MPTCP suboptions (80587). No controlled host-write/exploit is established by these primary descriptions.','These remote-network protocol flaws are CNA Critical and concern an interface members may reasonably associate with the shared TCP stack. A precise explanation that the protocol is absent is useful; severity is attributed rather than converted to demonstrated compromise.','Only archived Linux 6.12.95 build '+BASE+' with config SHA256 c10922b492fdf39ed3027b9c8f7ce2846a5d3799d57d417a161595fa81a64969: CONFIG_MPTCP is not set (line1360). Absent protocol code cannot be enabled by tenant sysctl. No claim about another build or all historical nodes.','Bind each relevant boot to this exact build or inspect its own configuration; preserve unknown intervals.',['config'])
add('53260 72069','propose','not_affected','exact-build-negative','53260: PREEMPT_RT request-socket timer publication can underflow lifetime refs. 72069: RT spin/rw unlock releases RCU before the lock operation finishes, permitting freed-lock access.','CNA Critical bugs in TCP/core locking sound broadly shared-host relevant; explaining the specific real-time-kernel prerequisite prevents a misleading implication that every server kernel is vulnerable.','Only the same exact archived 6.12.95 build/config: CONFIG_PREEMPT_RT is not set (line135). PREEMPT_DYNAMIC/PREEMPTION do not supply the RT lock substitutions. No other build or calendar history is classified.','Use typed boot/build identities for each interval; inspect any other kernel configuration separately.',['config'])
add('53341','conditional_review','not_affected','reference-profile-negative','A stale mnt_namespace is read during open_by_handle_at authorization; primary text limits security effect to an integer-comparison result leak, endless loop or crash.','Useful example of a mount-namespace/UAF report blocked by the reference tenant filter, but limited primary impact does not justify automatic high-threat selection solely from its CNA 7.8 score.','Only execution under pinned LXC common.seccomp 267e7844c122b9be56ca8a1ccc3d2f4d8986c326, which rejects open_by_handle_at with EPERM. Per-container overrides, host callers and actual installed filters are outside this negative scope. The fix is already in upstream 6.12.95.','Architect decides whether a limited-impact explanatory assessment merits inclusion; approved dossier must verify actual filter and exact build, not assume every container uses this profile.',['seccomp','config'],'Primary explicitly says it does not appear to have interesting security impact. Keep that contradiction to broad CNA scoring visible; do not describe arbitrary writes or demonstrated escalation.')
add('63830','propose','conditional','privileged-program','SK_MSG scatterlist ownership bits move inconsistently with entries; a later writable verdict can modify original splice-backed file page-cache pages.','Direct file-page integrity loss is a serious shared-kernel concern. Source permits unprivileged BPF, so members benefit from the distinction between ordinary socket filters and separately privileged SK_MSG programs.','Exact .95 loader requires CAP_BPF and CAP_NET_ADMIN in init_user_ns without a valid delegated token. A suitable host-installed SK_MSG program or explicitly delegated token can change exposure. Their absence was not measured.','Inspect actual permitted tokens, loaded/attached SK_MSG programs and relevant producer paths across boot history.',['bpf'])
add('74616','propose','conditional','privileged-program','XDP clone linear bytes overlap required skb_shared_info tailroom; later conversion writes corrupt XDP return metadata.','XDP/veth/network forwarding are plausible member concerns; concrete packet-metadata corruption is substantial even when configuring the affected XDP broadcast program requires host authority.','Exact .95 XDP program-load path needs initial-namespace CAP_BPF/CAP_NET_ADMIN or an allowed token. A preinstalled host XDP program/DEVMAP broadcast can process tenant/remote packets without the peer loading a program. No attached-program inventory was collected.','Confirm native/generic XDP/DEVMAP broadcast attachment, relevant ingress/devices, allowed tokens and frame geometry for each role/build.',['bpf'])
add('98039','propose','conditional','privileged-program','A plain allocation accepted as a percpu kptr is relocated or freed as a percpu allocation; primary description explicitly identifies arbitrary kernel read/write.','This is a concrete verifier type-confusion read/write threat. Explain why powerful BPF object/kfunc access differs from ordinary tenant socket-filter BPF instead of asserting all BPF is either enabled or safe.','Inherited primary/gate review requires a privileged program using object/percpu kptr operations, initial-namespace program authority or an explicitly allowed token/type. Tenant-userns capabilities alone are not enough; actual delegation/host programs are unknown.','Verify exact permitted program/kfunc/map/token operations and actual attached/loaded programs; do not infer absence from unprivileged_BPF policy alone.',['bpf'])
add('64355','conditional_review','conditional','privileged-program-review','DEVMAP broadcast clone retains fragment flag without valid shared-info metadata; frame return accesses invalid tail data.','A network datapath memory-safety flaw may justify a companion XDP assessment, but overlaps74616 and primary evidence does not establish an independent full exploit.','XDP/DEVMAP authority and host-installed program gates as 74616; no current attachment inventory.','Architect decides whether distinct explanatory value warrants another row; confirm exact XDP broadcast path before dossier.',['bpf'])
add('53092','conditional_review','conditional','privileged-program-review','Linked-register delta tracking reads a modified source register when source/destination alias, causing verifier/runtime bounds disagreement.','Verifier correctness is relevant but a full permitted tenant program bypass was not established; do not promote merely from a generic privilege-escalation narrative.','The relevant privileged verifier/program path needs exact capability/token/type qualification. Initial-userns authority and delegated-token masks remain separate from tenant-userns root.','Candidate-specific permitted verifier path and resulting unsafe access must be established before a substantive exposure conclusion.',['bpf'])
add('93045','conditional_review','conditional','privileged-program-review','An arena free below the arena base corrupts free-tree range offsets and permits later allocation below its mapping.','Serious memory-range bookkeeping flaw, but advanced BPF arena authority/delegation and exact behavior need clearer member-specific context than a blanket BPF list.','Inherited arena gate requires CAP_BPF and CAP_PERFMON or corresponding allowed token authority; unprivileged socket-filter enablement is insufficient.','Verify arena map/program compatibility, permitted token capabilities and concrete out-of-range effect on the scoped platform.',['bpf'])
add('64383 64384 64385 64386 64387 64597','propose','conditional','former-conditional-cifs','SMB2 replay/error-response lifetime mistakes double-free kernel response buffers in flush, notify, ioctl, query-info, directory or close replay paths.','CIFS/SMB is a common network-filesystem workload and previous public advisory5 (CIFSwitch) demonstrates topic relevance to members. Explain that module preload does not grant tenant mount creation, while host-prepared mounts remain possible.','Exact .95 and package-A inspected .113 cifs/smb3 filesystem registrations lack FS_USERNS_MOUNT. Tenant namespace root cannot create these kernel mounts; an operator-prepared/delegated mount or affected real host client workload can supply the prerequisite. Current and historical mounts remain unknown.','Inventory exact mounts/delegation, affected client calls, reconnect/replay and server response path per host/container role and build.',['cifs'])
add('89633','propose','conditional','former-conditional-cifs','SMB1 transaction DataOffset controls unchecked source/target pointers; coalesce_t2 memcpy can read/write outside the response buffer.','Concrete server-controlled heap read/write in a familiar filesystem merits assessment even if normal tenant mount creation is unavailable. Legacy protocol prerequisites can explain why many workloads do not apply.','Same initial-userns mount gate as the SMB2 rows; additionally an actual mount must negotiate SMB1. Exact .95 has CIFS_ALLOW_INSECURE_LEGACY=y and source defaults allow legacy dialects, but actual module parameter/dialect/mount state is unknown.','Identify relevant host/delegated mounts, negotiated dialect and module policy; no claim of universal SMB1 enablement or absence.',['cifs','config'])
add('89783','propose','conditional','former-conditional-module','XFRM6 appends one pointer beyond six-element xvec when secpath is full; primary notes the write remains inside sec_path allocation and UBSAN detects it.','IPv6/IPsec is tenant-relevant; a scoped explanation of the MIPv6 state/type prerequisite is useful, while CVSS9.8 does not prove arbitrary heap overwrite or host escape.','Exact .95 IPV6_MIP6=m compiles HAO receive call sites, but valid relevant XFRM state requires mip6 type registration. Not default-preloaded and autoload defaults off. Actual loaded modules/states/history are unknown.','Verify mip6 type registration, boot/module history, full secpath and states; built-in call-site presence alone is neither exposure nor absence proof.',['module','config'])
add('74597','propose','conditional','former-conditional-module','IPv6 tunnel ICMP reply inherits stale HAO control metadata, permitting address swap beyond quoted inner packet into skb_shared_info.','Concrete packet metadata corruption involving IPsec/tunnels is relevant, and explaining that IPv6 tunnel code is built in while the MIPv6 type is separate avoids a misleading module-based dismissal.','IPV6_TUNNEL=y is built in in exact .95. Relevant outer HAO/XFRM processing still needs mip6 types; MIP6 module is not preloaded and autoload defaults off. Actual module/state history unknown.','Verify exact HAO/XFRM type state and module history with tenant tunnel/ICMP path; do not claim ip6_tunnel absence.',['module','config'])
add('74746','propose','conditional','former-conditional-module','Flowtable GC can free a flow while insertion still uses it because original tuple is published before reply tuple.','nftables flow offload is a plausible VPS networking expectation, and a concrete kernel UAF deserves an explanation even where operator-only module activation prevents normal tenant setup.','Exact .95 NF_FLOW_TABLE/NFT_FLOW_OFFLOAD=m, absent default preload with autoload off; if operator activates them, tenant namespace CAP_NET_ADMIN can configure matching flow tables. No actual module/rule history collected.','Confirm module activation and actual flow-offload rules/traffic for each scoped boot and network namespace.',['module','config'])
add('98222','propose','conditional','former-conditional-module','Encrypted-key u16 allocation length truncates; primary KASAN reports a 32760-byte out-of-bounds copy into an undersized kernel buffer.','A large keyctl-related heap overwrite is a serious threat on an interface normally allowed by tenant seccomp. Explain why the separate encrypted-key type matters even though built-in asymmetric keys are available.','Exact .95 ENCRYPTED_KEYS=m, absent default preload and autoload disabled; keyctl is allowed but that alone does not register this key type. Operator module activation and permitted key input remain conditions; runtime history unknown.','Confirm encrypted-key type registration/module history and relevant key/master description permissions, then bind exact affected/fixed build.',['module','config'])
add('74607','conditional_review','conditional','special-hardware-review','Concurrent AMD SEV context copy/move/destroy can corrupt owner/mirror lists and drop a reference on the wrong VM.','KVM is delegated by default, so members may benefit from knowing this SEV-specific condition. Specific CPU/firmware/context access must be established; unrelated hardware CVEs are not being bulk-added.','KVM_AMD_SEV=y in archived .95 only proves code support. Actual AMD SEV hardware/firmware, contexts and required device/operation permission were not established. Do not call hardware absent or every KVM workload affected.','Establish exact SEV capability and context/device delegation for a real role/workload before inclusion/dossier; otherwise defer.',['config','followup'])
add('98041','defer','unknown','uncertainty-control','JMP32 pointer prediction is wrong, but alternate speculative-path validation remains unless bypass_spec_v1 applies.','Useful control against falsely equating unprivileged BPF enablement to an established verifier exploit. The weaker evidence is not upgraded just to enlarge the list.','A found that mitigations-off or initial/token CAP_PERFMON changes bypass_spec_v1; a working ordinary tenant bypass through the remaining branch validation was not established.','Resolve actual verifier/mitigation path and permission context before upgrading impact or exposure.',['bpf','followup'])
add('63823','defer','unknown','uncertainty-control','request_key_auth payload can be freed while an instantiate/reject path still uses target-key pointers.','Keys are relevant, but tenant keyctl alone does not prove access to the host helper/authentication context needed for the described race.','Required request-key helper/auth context availability and delegation are unmeasured. No absence or nonexposure conclusion is justified.','Establish an accessible helper/auth-key context and permitted instantiate lifecycle for the scoped tenant path.',['followup'])
assert len(rows)==26
assert collections.Counter(r['selection_decision'] for r in rows)=={'propose':19,'conditional_review':5,'defer':2}
proposal={'schema':1,'status':'completed_bounded_research_proposal_for_architect_reconciliation','approval':'No dossier/draft/publication approval; lead owns approval wording.','source_snapshot':CNA,'original_selection_sha256':hashlib.sha256((D/'selection.json').read_bytes()).hexdigest(),'original_41_carried_forward_ids':[r['cve'] for r in old['entries'] if r['decision']=='recommended'],'scope_bounds':{'focused_new_records':317,'unresolved_new_records':3128,'mechanical_range_records':3493,'fresh_enumeration':False,'note':'All 26 are from existing focused ledgers; this unit adds a relevance decision, not26 newly audited CVEs.'},'counts':dict(collections.Counter(r['selection_decision'] for r in rows)),'proposed_added_ids':[r['cve'] for r in rows if r['selection_decision']=='propose'],'gate_sources':G,'rows':rows,'limits':['Every source-scoped negative has unknown deployed applicability and unknown wider history.','Conditional is a research conclusion, not a new evaluator state or a replacement for conservative affected-history rules.','No typed runtime evidence, builds, exploits, external source downloads or advisory writes in this unit.','Formal CVSS remains attributed to Linux CNA; no score or severity invented.']}
(P/'proposal.json').write_text(json.dumps(proposal,indent=2)+'\n')
